// Java emitter (clients/java, package io.github.xantiagoma.xtandard.image):
// writes src/generated/java/io/github/xantiagoma/xtandard/image/ from the
// spec. That directory is a second source root (build-helper-maven-plugin),
// so the generated files sit in the library's package but outside
// src/main/java, which Spotless formats.
//
//   ProcessingMethods, InfoMethods, VideoMethods
//                    generic interfaces with one default method per option
//                    name and alias and argument shape (the typed option
//                    values); ProcessingOptions and the fluent chains
//                    implement them
//   OptionTables     name or alias to canonical name, canonical to short
//   QueryParams, ImaginaryParams
//                    native query keys and imaginary parameters, one typed
//                    method per key and alias
//   ImageFormat, VideoContainer, StreamProtocol, SegmentFormat,
//   SourceEncoding, SourceScheme, ImaginaryEndpoint
//                    enums of the spec's value lists
//   Constants        signing, encryption, URL and stream constants, error
//                    kinds and their statuses
//   InfoResponse, ErrorResponse and the records they reference
//                    the JSON bodies, decoded by the internal JSON parser
//
// Java 17: records, no pattern-matching switch. Nullability is JSpecify
// (@NullMarked package, @Nullable where null is allowed).

import { nameTable, type Shape, shapes, words } from "../lib.ts";
import type { CatalogueKind, Emitter, JSONSchema, Spec, SpecArg, SpecOption } from "../spec.ts";

const dir = "clients/java/src/generated/java/io/github/xantiagoma/xtandard/image/";
const pkg = "io.github.xantiagoma.xtandard.image";

const javaKeywords = new Set(
  (
    "abstract assert boolean break byte case catch char class const continue default do double else enum extends " +
    "final finally float for goto if implements import instanceof int interface long native new package private " +
    "protected public return short static strictfp super switch synchronized this throw throws transient try void " +
    "volatile while true false null var yield record sealed permits"
  ).split(" "),
);

/** Builder methods the per-option methods must not shadow (and java.lang.Object's). */
export const reservedMethods = new Set([
  "option",
  "options",
  "pipeline",
  "extension",
  "encoding",
  "withPdfPassword",
  "build",
  "param",
  "params",
  "entries",
  "isEmpty",
  "self",
  "create",
  "toString",
  "equals",
  "hashCode",
  "getClass",
  "notify",
  "notifyAll",
  "wait",
  "clone",
  "finalize",
]);

/** camelCase Java identifier of a name ("min-width" → "minWidth", "R" → "r"). */
function camel(name: string): string {
  const ws = words(name);
  let id = ws.map((w, i) => (i === 0 ? w.toLowerCase() : w[0]!.toUpperCase() + w.slice(1).toLowerCase())).join("");
  if (id === "") id = "value";
  if (/^[0-9]/.test(id)) id = `v${id}`;
  return javaKeywords.has(id) ? `${id}Value` : id;
}

/** UPPER_SNAKE constant name of a value ("fill-down" → "FILL_DOWN", "m3u8" → "M3U8"). */
function constant(value: string): string {
  let id = words(value)
    .map((w) => w.toUpperCase())
    .join("_");
  if (/^[0-9]/.test(id)) id = `V${id}`;
  return id;
}

const str = (s: string) => JSON.stringify(s);

const header = (what: string) =>
  [
    `// Code generated by clients/codegen/emitters/java.ts from clients/spec/spec.json. DO NOT EDIT.`,
    `// Run \`task clients:generate\`. ${what}`,
    "",
    `package ${pkg};`,
    "",
  ].join("\n");

/** Text for a Javadoc comment: HTML-escaped, no comment terminators, no unicode escapes. */
function jd(text: string): string {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("\\", "&#92;")
    .replaceAll("*/", "*&#47;")
    .replaceAll("@", "&#64;")
    .replaceAll("{", "&#123;")
    .replaceAll("}", "&#125;");
}

/** A Javadoc block at an indent; lines starting with "@" are block tags. */
function javadoc(lines: string[], indent: string): string {
  const out = [`${indent}/**`];
  for (const l of lines) {
    for (const part of l.split("\n")) out.push(part === "" ? `${indent} *` : `${indent} * ${part}`);
  }
  out.push(`${indent} */`);
  return out.join("\n");
}

// ---- option methods ---------------------------------------------------------

interface Param {
  /** Java type as written in the signature. */
  type: string;
  /** Erasure, for duplicate detection. */
  erasure: string;
  name: string;
  doc: string;
}

/** Java type of one argument in a method signature. */
function argType(a: SpecArg): { type: string; erasure: string } {
  const nullable = a.nullable;
  switch (a.type) {
    case "integer":
      return nullable ? { type: "@Nullable Number", erasure: "Number" } : { type: "long", erasure: "long" };
    case "number":
      return nullable ? { type: "@Nullable Number", erasure: "Number" } : { type: "double", erasure: "double" };
    case "boolean":
      return nullable ? { type: "@Nullable Boolean", erasure: "Boolean" } : { type: "boolean", erasure: "boolean" };
    case "direction":
      return nullable ? { type: "@Nullable Object", erasure: "Object" } : { type: "Object", erasure: "Object" };
    default:
      return nullable ? { type: "@Nullable String", erasure: "String" } : { type: "String", erasure: "String" };
  }
}

function argDoc(a: SpecArg): string {
  const parts: string[] = [];
  if (a.doc) parts.push(a.doc);
  if (a.type === "enum" && a.enum) parts.push(`one of ${a.enum.map((v) => `"${v}"`).join(", ")}`);
  if (a.type === "direction") parts.push(`"down", "up", "left", "right" or a number`);
  if (a.type === "color") parts.push("a hex colour");
  if (a.type === "base64") parts.push("URL-safe base64");
  if (a.min !== undefined && a.max !== undefined) parts.push(`${a.min} to ${a.max}`);
  else if (a.min !== undefined) parts.push(`at least ${a.min}`);
  else if (a.max !== undefined) parts.push(`at most ${a.max}`);
  if (a.nullable) parts.push("null writes an empty argument");
  return parts.join("; ") || a.name;
}

/** The varargs element type of a rest group. */
function restType(rest: readonly SpecArg[]): { type: string; erasure: string } {
  const ts = [...new Set(rest.map((a) => argType(a).type))];
  if (ts.length === 1) {
    const t = argType(rest[0]!);
    return { type: `${t.type}...`, erasure: `${t.erasure}[]` };
  }
  return { type: "@Nullable Object...", erasure: "Object[]" };
}

function shapeParams(s: Shape): { params: Param[]; rest?: Param } {
  const used = new Map<string, number>();
  const name = (n: string) => {
    let id = camel(n);
    const c = used.get(id) ?? 0;
    used.set(id, c + 1);
    if (c > 0) id = `${id}${c + 1}`;
    return id;
  };
  const params = s.fixed.map((a) => ({ ...argType(a), name: name(a.name), doc: argDoc(a) }));
  if (!s.rest) return { params };
  const rt = restType(s.rest);
  const restDoc = `repeated ${s.rest.map((a) => a.name).join(", ")}: ${s.rest.map(argDoc).join(" / ")}`;
  return { params, rest: { ...rt, name: name(s.rest.length === 1 ? `${s.rest[0]!.name}s` : "rest"), doc: restDoc } };
}

function optionDoc(o: SpecOption): string[] {
  const lines = [jd(o.doc), "", "<p>" + jd(`URL names: ${[o.name, ...o.aliases].join(", ")}; arguments ${o.syntax}; default ${o.default}.`)];
  const tags: string[] = [];
  if (o.milestone) tags.push(`milestone ${o.milestone}`);
  tags.push(`scope ${o.scope}`);
  if (o.pro) tags.push("imgproxy Pro option (free here)");
  if (o.security) tags.push("security option (needs XI_SECURITY_ALLOW_SECURITY_OPTIONS)");
  if (o.removed) tags.push("removed: accepted and ignored");
  lines.push(jd(`${tags.join("; ")}.`));
  return lines;
}

const kindPrefix: Record<CatalogueKind, string> = { processing: "Processing", info: "Info", video: "Video" };

function emitMethods(spec: Spec, kind: CatalogueKind): string {
  const K = kindPrefix[kind];
  const out: string[] = [header(`The typed ${kind} option methods.`)];
  out.push("import org.jspecify.annotations.Nullable;");
  out.push("");
  out.push(
    javadoc(
      [
        `One method per ${kind} option name and alias, with one overload per argument shape; each appends`,
        "that option, written with the name as called (option names {@code GIVEN}), its short name (default)",
        "or its canonical name.",
        "",
        "<p>Numbers are written as ECMAScript writes them ({@code 300}, {@code 1.5}), booleans as {@code 1}",
        "and {@code 0}, and a null argument is an empty one.",
        "",
        "@param <S> the implementing type, returned by every method",
      ],
      "",
    ),
  );
  out.push(`public interface ${K}Methods<S extends ${K}Methods<S>> {`);
  out.push("");
  out.push(
    javadoc(
      [
        "Appends one option occurrence (what the per-option methods call).",
        "",
        "@param name an option name or alias",
        "@param args the arguments: strings, numbers, booleans or null (an empty argument)",
        "@return this",
      ],
      "  ",
    ),
  );
  out.push("  S option(String name, @Nullable Object... args);");
  const used = new Map<string, string>();
  for (const o of spec.options[kind]) {
    const allShapes = shapes(o).map(shapeParams);
    for (const n of [o.name, ...o.aliases]) {
      const id = camel(n);
      if (reservedMethods.has(id)) throw new Error(`${kind} option ${n} collides with the builder method ${id}`);
      const prev = used.get(id);
      if (prev !== undefined) throw new Error(`${kind} option names ${prev} and ${n} are both the Java method ${id}`);
      used.set(id, n);
      const seen = new Set<string>();
      for (const sh of allShapes) {
        const erasure = [...sh.params.map((p) => p.erasure), ...(sh.rest ? [sh.rest.erasure] : [])].join(",");
        if (seen.has(erasure)) continue;
        seen.add(erasure);
        const ps = [...sh.params, ...(sh.rest ? [sh.rest] : [])];
        out.push("");
        out.push(
          javadoc(
            [...optionDoc(o), "", ...ps.map((p) => `@param ${p.name} ${jd(p.doc)}`), "@return this"],
            "  ",
          ),
        );
        const sig = ps.map((p) => `${p.type} ${p.name}`).join(", ");
        out.push(`  default S ${id}(${sig}) {`);
        const fixed = sh.params.map((p) => p.name).join(", ");
        if (sh.rest) {
          out.push(
            `    return option(${str(n)}, Args.concat(new @Nullable Object[] {${fixed}}, ${sh.rest.name}));`,
          );
        } else {
          out.push(`    return option(${str(n)}${fixed ? `, ${fixed}` : ""});`);
        }
        out.push("  }");
      }
      if (allShapes.length === 0) throw new Error(`${kind} option ${o.name} has no argument shapes`);
    }
  }
  out.push("}");
  out.push("");
  return out.join("\n");
}

function mapLiteral(entries: [string, string][], indent: string): string {
  return entries.map(([k, v]) => `${indent}Map.entry(${str(k)}, ${str(v)})`).join(",\n");
}

function emitTables(spec: Spec): string {
  const out: string[] = [header("Option name tables of the processing, /info and /video catalogues.")];
  out.push("import java.util.Map;");
  out.push("");
  out.push("/** Option name tables: every name and alias to its canonical name, and canonical to short names. */");
  out.push("final class OptionTables {");
  out.push("  private OptionTables() {}");
  for (const kind of ["processing", "info", "video"] as const) {
    const opts = spec.options[kind];
    const K = kind.toUpperCase();
    out.push("");
    out.push(`  /** ${kind} option name or alias to canonical name. */`);
    out.push(`  static final Map<String, String> ${K}_NAMES =`);
    out.push("      Map.ofEntries(");
    out.push(`${mapLiteral(nameTable(opts), "          ")});`);
    out.push("");
    out.push(`  /** Canonical ${kind} option name to the name builders write by default (the shortest). */`);
    out.push(`  static final Map<String, String> ${K}_SHORT =`);
    out.push("      Map.ofEntries(");
    out.push(`${mapLiteral(opts.map((o) => [o.name, o.short]), "          ")});`);
  }
  out.push("}");
  out.push("");
  return out.join("\n");
}

// ---- enums and constants ----------------------------------------------------

function emitEnum(name: string, doc: string, values: { value: string; doc?: string }[], extra: string[] = []): string {
  const out: string[] = [header(doc)];
  out.push(`/** ${jd(doc)} */`);
  out.push(`public enum ${name} {`);
  values.forEach((v, i) => {
    if (v.doc) out.push(`  /** ${jd(v.doc)} */`);
    else out.push(`  /** {@code ${jd(v.value)}}. */`);
    out.push(`  ${constant(v.value)}(${str(v.value)})${i === values.length - 1 ? ";" : ","}`);
  });
  out.push("");
  out.push("  private final String value;");
  out.push("");
  out.push(`  ${name}(String value) {`);
  out.push("    this.value = value;");
  out.push("  }");
  out.push("");
  out.push("  /**");
  out.push("   * The value as written in URLs.");
  out.push("   *");
  out.push("   * @return the value");
  out.push("   */");
  out.push("  public String value() {");
  out.push("    return value;");
  out.push("  }");
  out.push("");
  out.push("  @Override");
  out.push("  public String toString() {");
  out.push("    return value;");
  out.push("  }");
  for (const e of extra) out.push(e);
  out.push("}");
  out.push("");
  return out.join("\n");
}

function listLiteral(values: readonly (string | number)[]): string {
  return `List.of(${values.map((v) => (typeof v === "string" ? str(v) : String(v))).join(", ")})`;
}

function emitConstants(spec: Spec): string {
  const s = spec.media.streams;
  const sg = spec.signing;
  const en = spec.encryption;
  const u = spec.url;
  const out: string[] = [header("Constants of the client specification.")];
  out.push("import java.util.List;");
  out.push("import java.util.Map;");
  out.push("");
  out.push("/** Constants of the client specification (clients/spec/spec.json): signing, encryption, URLs, streams. */");
  out.push("public final class Constants {");
  out.push("  private Constants() {}");
  const c = (doc: string, decl: string) => {
    out.push("");
    out.push(`  /** ${jd(doc)} */`);
    out.push(`  public static final ${decl};`);
  };
  c("Version of the spec these classes were generated from.", `int SPEC_VERSION = ${spec.spec_version}`);
  c("Smallest signature size in bytes.", `int MIN_SIGNATURE_SIZE = ${sg.min_size}`);
  c("Largest signature size in bytes.", `int MAX_SIGNATURE_SIZE = ${sg.max_size}`);
  c("Default signature size in bytes (XI_SIGNING_SIZE).", `int DEFAULT_SIGNATURE_SIZE = ${sg.default_size}`);
  c("Signature segments of unsigned URLs.", `List<String> UNSIGNED_PLACEHOLDERS = ${listLiteral(sg.unsigned_placeholders)}`);
  c("Default signature segment of unsigned URLs.", `String DEFAULT_UNSIGNED = ${str(sg.default_unsigned)}`);
  c("Query parameter of the xi_sig signature.", `String XI_SIG_PARAM = ${str(sg.query_param)}`);
  c("AES key sizes in bytes.", `List<Integer> ENCRYPTION_KEY_SIZES = ${listLiteral(en.key_sizes)}`);
  c("AES-CBC IV size in bytes.", `int IV_SIZE = ${en.iv_size}`);
  c("Prefix of encrypted sources.", `String ENCRYPTED_SOURCE_PREFIX = ${str(en.source_prefix)}`);
  c("Longest PDF password in UTF-8 bytes.", `int MAX_PDF_PASSWORD_BYTES = ${en.max_pdf_password_bytes}`);
  c("Canonical name of the PDF password option.", `String PDF_PASSWORD_NAME = ${str(en.pdf_password_names[0]!)}`);
  c("Short name of the PDF password option.", `String PDF_PASSWORD_SHORT = ${str(en.pdf_password_short_name)}`);
  c("Default argument separator.", `String DEFAULT_SEPARATOR = ${str(u.default_separator)}`);
  c("Separators the imgproxy grammar forbids.", `List<String> FORBIDDEN_SEPARATORS = ${listLiteral(u.forbidden_separators)}`);
  c(
    "Separators the query dialect forbids inside o=.",
    `List<String> FORBIDDEN_QUERY_SEPARATORS = ${listLiteral(u.forbidden_query_separators)}`,
  );
  c("Segment between chained pipelines.", `String PIPELINE_SEPARATOR = ${str(u.pipeline_separator)}`);
  c("Characters a plain source keeps verbatim besides ASCII letters and digits.", `String PLAIN_SAFE = ${str(u.plain_safe)}`);
  c("Characters a query key or value keeps verbatim besides ASCII letters and digits.", `String QUERY_SAFE = ${str(u.query_safe)}`);
  c("Pattern an extension must match.", `String EXTENSION_PATTERN = ${str(u.extension_pattern)}`);
  c("Pattern of xi:// source names.", `String XI_NAME_PATTERN = ${str(spec.sources.xi_name_pattern)}`);
  c("Default mount of the query dialect (XI_DIALECTS_QUERY_PREFIX).", `String QUERY_MOUNT = ${str(spec.query.mount)}`);
  out.push("");
  out.push("  /** /q/video keys written differently from the /video option name. */");
  out.push("  public static final Map<String, String> NATIVE_VIDEO_KEYS =");
  out.push(
    `      Map.ofEntries(\n${mapLiteral(Object.entries(spec.query.native_video_keys).sort() as [string, string][], "          ")});`,
  );
  c("Most renditions of one stream.", `int MAX_RENDITIONS = ${s.max_renditions}`);
  c("Smallest rendition (short side of the frame).", `int RENDITION_MIN = ${s.rendition_min}`);
  c("Largest rendition (short side of the frame).", `int RENDITION_MAX = ${s.rendition_max}`);
  c("Shortest segment duration in seconds.", `int SEGMENT_DURATION_MIN = ${s.segment_duration_min}`);
  c("Longest segment duration in seconds.", `int SEGMENT_DURATION_MAX = ${s.segment_duration_max}`);
  out.push("");
  out.push("  /** Error kinds of the server's JSON error envelope, with their HTTP status. */");
  out.push("  public static final Map<String, Integer> ERROR_STATUS =");
  out.push(
    `      Map.ofEntries(\n${spec.error_kinds.map((e) => `          Map.entry(${str(e.kind)}, ${e.status})`).join(",\n")});`,
  );
  out.push("}");
  out.push("");
  return out.join("\n");
}

function emitEnums(spec: Spec): Record<string, string> {
  const s = spec.media.streams;
  const files: Record<string, string> = {};
  files["ImageFormat"] = emitEnum(
    "ImageFormat",
    "Output formats of the processing format option.",
    spec.media.image_formats.map((value) => ({ value })),
  );
  files["VideoContainer"] = emitEnum(
    "VideoContainer",
    "Output containers of /video URLs.",
    spec.media.video_containers.map((value) => ({ value })),
  );
  const proto = (name: string) => s.protocols.find((p) => p.name === name)!;
  files["StreamProtocol"] = emitEnum(
    "StreamProtocol",
    "Adaptive streaming protocols: HLS or DASH.",
    s.protocols.map((p) => ({ value: p.name, doc: `${p.name}: a ${p.container} manifest (${p.content_type}).` })),
    [
      "",
      "  /**",
      "   * The manifest container, the extension of a stream URL.",
      "   *",
      "   * @return {@code m3u8} or {@code mpd}",
      "   */",
      "  public String container() {",
      "    return switch (this) {",
      ...s.protocols.map((p) => `      case ${constant(p.name)} -> ${str(proto(p.name).container)};`),
      "    };",
      "  }",
      "",
      "  /**",
      "   * The manifest media type.",
      "   *",
      "   * @return the Content-Type of the manifest",
      "   */",
      "  public String contentType() {",
      "    return switch (this) {",
      ...s.protocols.map((p) => `      case ${constant(p.name)} -> ${str(p.content_type)};`),
      "    };",
      "  }",
    ],
  );
  const def = s.segment_formats.find((f) => f.default)!;
  files["SegmentFormat"] = emitEnum(
    "SegmentFormat",
    "Stream segment containers.",
    s.segment_formats.map((f) => ({
      value: f.name,
      doc: `${f.name} (aliases ${f.aliases.join(", ")}): ${f.protocols.join(" and ")}${f.default ? "; the default" : ""}.`,
    })),
    [
      "",
      "  /** The default segment format, which stream URLs leave out. */",
      `  public static final SegmentFormat DEFAULT = ${constant(def.name)};`,
      "",
      "  /**",
      "   * The protocols that accept this segment format.",
      "   *",
      "   * @return protocol names",
      "   */",
      "  public java.util.List<String> protocols() {",
      "    return switch (this) {",
      ...s.segment_formats.map(
        (f) => `      case ${constant(f.name)} -> ${listLiteral(f.protocols).replace("List.of", "java.util.List.of")};`,
      ),
      "    };",
      "  }",
    ],
  );
  files["SourceEncoding"] = emitEnum(
    "SourceEncoding",
    "How a source is written in an imgproxy URL.",
    spec.sources.encodings.map((value) => ({ value })),
  );
  files["SourceScheme"] = emitEnum(
    "SourceScheme",
    "Source schemes the server resolves.",
    spec.sources.schemes.map((x) => ({ value: x.scheme, doc: `${x.scheme}: authority ${x.authority}, e.g. ${x.example}.` })),
  );
  files["ImaginaryEndpoint"] = emitEnum(
    "ImaginaryEndpoint",
    "imaginary endpoints of /q/<endpoint>.",
    spec.query.imaginary.endpoints.map((value) => ({ value })),
  );
  return files;
}

// ---- query parameters -------------------------------------------------------

function emitParams(name: string, doc: string, keys: { name: string; aliases: string[]; doc: string }[]): string {
  const out: string[] = [header(doc)];
  out.push(
    javadoc(
      [
        jd(doc),
        "",
        "<p>Keys are written in the order they are added, after {@code url}; booleans are {@code true} or",
        "{@code false} and numbers are written as ECMAScript writes them. {@link #param} adds any key.",
      ],
      "",
    ),
  );
  out.push(`public final class ${name} extends ParamList<${name}> {`);
  out.push("");
  out.push(`  private ${name}() {}`);
  out.push("");
  out.push("  /**");
  out.push("   * Starts an empty parameter list.");
  out.push("   *");
  out.push("   * @return a new list");
  out.push("   */");
  out.push(`  public static ${name} create() {`);
  out.push(`    return new ${name}();`);
  out.push("  }");
  out.push("");
  out.push("  @Override");
  out.push(`  ${name} self() {`);
  out.push("    return this;");
  out.push("  }");
  const used = new Set<string>();
  for (const k of keys) {
    for (const n of [k.name, ...k.aliases]) {
      const id = camel(n);
      if (reservedMethods.has(id))
        throw new Error(`${name} key ${n} collides with the method ${id}`);
      if (used.has(id)) throw new Error(`${name} keys collide on ${id}`);
      used.add(id);
      for (const [t, what] of [
        ["String", "the value"],
        ["long", "the value"],
        ["double", "the value"],
        ["boolean", "the value, written true or false"],
      ] as const) {
        out.push("");
        out.push(
          javadoc(
            [
              jd(k.doc || `The ${k.name} parameter.`),
              "",
              jd(`Key ${n}${k.aliases.length ? ` (names: ${[k.name, ...k.aliases].join(", ")})` : ""}.`),
              "",
              `@param value ${what}`,
              "@return this",
            ],
            "  ",
          ),
        );
        out.push(`  public ${name} ${id}(${t} value) {`);
        out.push(`    return param(${str(n)}, value);`);
        out.push("  }");
      }
    }
  }
  out.push("}");
  out.push("");
  return out.join("\n");
}

// ---- response records -------------------------------------------------------

interface JType {
  /** Declared type of a nullable component. */
  boxed: string;
  /** Declared type of a required component (primitive where possible). */
  required: string;
  /** Expression decoding JSON value `v` (an Object) at `where`; `d` numbers nested lambda parameters. */
  decode: (v: string, where: string, d: number) => string;
}

function schemaJType(s: JSONSchema): JType {
  if (s.$ref) {
    const n = s.$ref.replace("#/components/schemas/", "");
    return { boxed: n, required: n, decode: (v, w) => `${n}.fromJsonValue(${v}, ${w})` };
  }
  const types = (s.type === undefined ? [] : Array.isArray(s.type) ? s.type : [s.type]).filter((t) => t !== "null");
  const t = types.length === 1 ? types[0] : undefined;
  switch (t) {
    case "string":
      return { boxed: "String", required: "String", decode: (v, w) => `JsonValues.string(${v}, ${w})` };
    case "integer":
      return { boxed: "Long", required: "long", decode: (v, w) => `JsonValues.integer(${v}, ${w})` };
    case "number":
      return { boxed: "Double", required: "double", decode: (v, w) => `JsonValues.number(${v}, ${w})` };
    case "boolean":
      return { boxed: "Boolean", required: "boolean", decode: (v, w) => `JsonValues.bool(${v}, ${w})` };
    case "array": {
      const e = s.items ? schemaJType(s.items) : undefined;
      if (!e) {
        return {
          boxed: "List<@Nullable Object>",
          required: "List<@Nullable Object>",
          decode: (v, w) => `JsonValues.rawList(${v}, ${w})`,
        };
      }
      const et = e.boxed;
      return {
        boxed: `List<${et}>`,
        required: `List<${et}>`,
        decode: (v, w, d) =>
          `JsonValues.list(${v}, ${w}, (x${d}, w${d}) -> ${e.decode(`JsonValues.nonNull(x${d}, w${d})`, `w${d}`, d + 1)})`,
      };
    }
    case "object": {
      if (s.properties) throw new Error("inline object schemas are not supported");
      const ap = s.additionalProperties;
      if (typeof ap === "object" && (ap.type !== undefined || ap.$ref !== undefined)) {
        const e = schemaJType(ap);
        return {
          boxed: `Map<String, ${e.boxed}>`,
          required: `Map<String, ${e.boxed}>`,
          decode: (v, w, d) =>
            `JsonValues.map(${v}, ${w}, (x${d}, w${d}) -> ${e.decode(`JsonValues.nonNull(x${d}, w${d})`, `w${d}`, d + 1)})`,
        };
      }
      return {
        boxed: "Map<String, @Nullable Object>",
        required: "Map<String, @Nullable Object>",
        decode: (v, w) => `JsonValues.rawMap(${v}, ${w})`,
      };
    }
    default:
      return { boxed: "Object", required: "Object", decode: (v) => v };
  }
}

function emitRecord(name: string, s: JSONSchema): string {
  const out: string[] = [header(`The ${name} JSON body.`)];
  const props = Object.entries(s.properties ?? {});
  const req = new Set(s.required ?? []);
  const comps = props.map(([p, ps]) => {
    const id = camel(p);
    const t = schemaJType(ps);
    const required = req.has(p);
    const nullableType = (ps.type !== undefined && Array.isArray(ps.type) && ps.type.includes("null")) || !required;
    return { json: p, id, t, required: required && !nullableType, doc: ps.description };
  });
  const usesList = comps.some((c) => c.t.boxed.startsWith("List<"));
  const usesMap = comps.some((c) => c.t.boxed.includes("Map<"));
  if (usesList) out.push("import java.util.List;");
  if (usesMap) out.push("import java.util.Map;");
  out.push("import org.jspecify.annotations.Nullable;");
  out.push("");
  const docLines = [jd(s.description ?? `The ${name} object.`).split("\n").join("\n<br>")];
  docLines.push("");
  for (const c of comps) {
    docLines.push(`@param ${c.id} {@code ${jd(c.json)}}${c.doc ? `: ${jd(c.doc)}` : ""}${c.required ? "" : " (null when absent)"}`);
  }
  out.push(javadoc(docLines, ""));
  out.push(`public record ${name}(`);
  out.push(
    comps
      .map((c) => {
        const t = c.required ? c.t.required : `@Nullable ${c.t.boxed}`;
        return `    ${t} ${c.id}`;
      })
      .join(",\n") + ") {",
  );
  out.push("");
  out.push("  /**");
  out.push(`   * Decodes {@code ${name}} JSON text.`);
  out.push("   *");
  out.push("   * @param json the JSON document");
  out.push(`   * @return the decoded value`);
  out.push("   * @throws IllegalArgumentException the text is not JSON or does not have this shape");
  out.push("   */");
  out.push(`  public static ${name} fromJson(String json) {`);
  out.push(`    return fromJsonValue(Json.parse(json), ${str(name)});`);
  out.push("  }");
  out.push("");
  out.push(`  static ${name} fromJsonValue(@Nullable Object value, String where) {`);
  out.push(`    Map<String, @Nullable Object> o = JsonValues.object(value, where);`);
  out.push(`    return new ${name}(`);
  out.push(
    comps
      .map((c) => {
        const w = `where + ${str("." + c.json)}`;
        const get = `o.get(${str(c.json)})`;
        if (c.required) return `        ${c.t.decode(`JsonValues.required(o, ${str(c.json)}, where)`, w, 0)}`;
        return `        JsonValues.optional(${get}, ${w}, (x, xw) -> ${c.t.decode("JsonValues.nonNull(x, xw)", "xw", 0)})`;
      })
      .join(",\n") + ");",
  );
  out.push("  }");
  out.push("}");
  out.push("");
  let text = out.join("\n");
  if (!usesMap) text = text.replace("import org.jspecify", "import java.util.Map;\nimport org.jspecify");
  return text;
}

export const emitter: Emitter = {
  language: "java",
  emit(spec) {
    const files: Record<string, string> = {};
    for (const kind of ["processing", "info", "video"] as const) {
      files[`${dir}${kindPrefix[kind]}Methods.java`] = emitMethods(spec, kind);
    }
    files[`${dir}OptionTables.java`] = emitTables(spec);
    files[`${dir}Constants.java`] = emitConstants(spec);
    for (const [n, text] of Object.entries(emitEnums(spec))) files[`${dir}${n}.java`] = text;
    files[`${dir}QueryParams.java`] = emitParams(
      "QueryParams",
      "Native keys of the query dialect's image endpoint (/q/?url=…&w=300&f=webp).",
      spec.query.image_keys,
    );
    const reservedImaginary = new Set(["url", "sign", "xi_sig"]);
    files[`${dir}ImaginaryParams.java`] = emitParams(
      "ImaginaryParams",
      "Parameters of the query dialect's imaginary endpoints (/q/resize?url=…&width=300).",
      spec.query.imaginary.params.filter((p) => !reservedImaginary.has(p)).map((p) => ({ name: p, aliases: [], doc: "" })),
    );
    for (const [n, s] of Object.entries(spec.response_schemas).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
      files[`${dir}${n}.java`] = emitRecord(n, s);
    }
    return files;
  },
};
